`+e),alert("Copiado al portapapeles")}catch{try{alert(e)}catch{}}}var O=["\u{1F30E} \xC9tica de lo suficiente, no del acumular","\u{1F33F} Parte viva de la comunidad terrenal, no due\xF1a","\u{1F4A7}\u{1F32C}\uFE0F\u{1F525} Aire, agua, suelo, monta\xF1a, \xE1rbol, animal: familia","\u267B\uFE0F Frugal, consciente y regenerativo","\u2764\uFE0F Afectivo, espiritual y comunitario","\u270A No al individualismo, lucro desmedido y mercantilizaci\xF3n de la vida"],C=[{nombre:"K\xFCme Mongen",pueblo:"Pueblo Mapuche",conti:"Abya Yala",sig:"\u201Cbuen vivir\u201D",ico:"\u{1F30E}",texto:"Conexi\xF3n profunda con la naturaleza, en equilibrio con las fuerzas y seres que la habitan. Armon\xEDa entre el agua, el territorio, la vida personal, familiar y comunitaria, la cultura y las energ\xEDas espirituales. Reconstruir el K\xFCme Mongen es reconstruir una sociedad con dignidad, solidaridad y reciprocidad para todos los pueblos. Es, ante todo, una lucha por amor a la vida."},{nombre:"Sumak Kawsay",pueblo:"Pueblo Kichwa \xB7 Ecuador",conti:"Abya Yala",sig:"\u201Cvida plena en armon\xEDa\u201D",ico:"\u{1F30E}",texto:"Gu\xEDa las relaciones dentro del Ayllu (comunidad) y entre la comunidad y la naturaleza. Vivir en equilibrio con los r\xEDos, los bosques, las monta\xF1as, los esp\xEDritus protectores y los dioses: todo est\xE1 interconectado y merece respeto."},{nombre:"\xD1ande Reko",pueblo:"Pueblo Guaran\xED",conti:"Abya Yala",sig:"\u201Cnuestro modo de ser\u201D",ico:"\u{1F30E}",texto:"Libertad, alegr\xEDa comunitaria, reciprocidad y convite. Todo orientado a la b\xFAsqueda de la Tierra Sin Mal: un mundo justo, en paz y en plenitud."},{nombre:"Vivir Bien",pueblo:"Pueblo Kolla \xB7 Argentina",conti:"Abya Yala",sig:"crecer con la naturaleza",ico:"\u{1F30E}",texto:"Crecer con la naturaleza, no contra ella. Como dice el sabio Huanacuni: \u201CEl ser humano es tierra que anda\u201D. La vida florece solo cuando se respeta ese v\xEDnculo sagrado."},{nombre:"Shiir Waras",pueblo:"Pueblo Shuar \xB7 Ecuador",conti:"Abya Yala",sig:"\u201Cbuen vivir\u201D",ico:"\u{1F30E}",texto:"Paz dom\xE9stica y vida armoniosa, en equilibrio con la familia, la comunidad y la naturaleza. Bienestar integral, tejido en el d\xEDa a d\xEDa."},{nombre:"Balu Wala",pueblo:"Pueblo Guna \xB7 Panam\xE1 y Colombia",conti:"Abya Yala",sig:"\u201C\xE1rbol de sal\u201D",ico:"\u{1F30E}",texto:"Eje filos\xF3fico de la existencia guna: relaci\xF3n indisoluble entre humanidad, naturaleza y universo, fundada en el respeto, la equidad y la armon\xEDa. Gu\xEDa las relaciones pol\xEDticas, econ\xF3micas y sociales, y fortalece la producci\xF3n comunitaria y la calidad de vida colectiva, desde la memoria y el presente comunitario."},{nombre:"Suma Qama\xF1a",pueblo:"Pueblos Aymara y Quechua \xB7 Andes",conti:"Abya Yala",sig:"\u201Cvivir bien\u201D",ico:"\u{1F30E}",texto:"Paradigma andino: relacionalidad, complementariedad, ciclicidad, correspondencia y conciencia natural. La vida es un todo org\xE1nico donde dialogan Jaqi (seres humanos), Wak\u2019a (divinidades) y Sallqa (naturaleza silvestre). Con-vivir en armon\xEDa con la Tierra, el mundo espiritual y las futuras generaciones."},{nombre:"Lekil Kuxlejal",pueblo:"Pueblos Maya Tseltal y Tsotsil \xB7 Chiapas",conti:"Abya Yala",sig:"\u201Cvida buena y justa para todos\u201D",ico:"\u{1F30E}",texto:"Vida buena que solo es buena si es compartida: tierra comunal, asamblea que decide, fiesta que une y trabajo que dignifica. Sin justicia y sin comunidad no hay bienestar verdadero."},{nombre:"Kawsak Sacha",pueblo:"Pueblo Kichwa amaz\xF3nico \xB7 Sarayaku, Ecuador",conti:"Abya Yala",sig:"\u201Cselva viviente\u201D",ico:"\u{1F30E}",texto:"La selva es un ser vivo y sagrado, con due\xF1os y esp\xEDritus que la cuidan. Defender el territorio es defender la vida misma: el petr\xF3leo y la mina no entran donde la selva habla y ense\xF1a."},{nombre:"Ubuntu",pueblo:"Pueblos Zul\xFA y Xhosa \xB7 Sud\xE1frica",conti:"\xC1frica",sig:"\u201Csoy porque somos\u201D",ico:"\u{1F30D}",texto:"\u201CUna persona es persona a trav\xE9s de otras personas\u201D. La identidad y el bienestar nacen del v\xEDnculo: cuidar al otro, compartir lo que hay, perdonar y reparar. Sin comunidad no hay humanidad plena."},{nombre:"Harambee",pueblo:"Pueblos de Kenia",conti:"\xC1frica",sig:"\u201Ctiremos juntos\u201D",ico:"\u{1F30D}",texto:"Trabajo colectivo y ayuda mutua: toda la aldea levanta la casa, cosecha o enfrenta la dificultad. Nadie se salva solo; la fuerza est\xE1 en tirar la cuerda al mismo tiempo y repartir el fruto."},{nombre:"Teranga",pueblo:"Pueblo Wolof \xB7 Senegal",conti:"\xC1frica",sig:"\u201Chospitalidad que comparte\u201D",ico:"\u{1F30D}",texto:"El honor est\xE1 en recibir bien: al visitante se le da techo, plato y palabra. Compartir comida y tiempo no empobrece, multiplica la alegr\xEDa y teje paz entre familias y pueblos."},{nombre:"Ujamaa",pueblo:"Tanzania \xB7 legado de Nyerere",conti:"\xC1frica",sig:"\u201Cfamilia extendida\u201D",ico:"\u{1F30D}",texto:"La aldea como familia grande: tierra en com\xFAn, decisiones en asamblea y econom\xEDa al servicio de todos. Nadie avanza pisando al vecino; el desarrollo se mide en dignidad compartida."},{nombre:"Sankofa",pueblo:"Pueblo Akan \xB7 Ghana",conti:"\xC1frica",sig:"\u201Cvuelve y recoge lo olvidado\u201D",ico:"\u{1F30D}",texto:"El p\xE1jaro que mira atr\xE1s para avanzar: recoger la sabidur\xEDa de los ancestros antes de caminar al futuro. Quien olvida su ra\xEDz, pierde el camino; quien la honra, florece."},{nombre:"Sarvodaya",pueblo:"India \xB7 legado de Gandhi",conti:"Asia",sig:"\u201Cbienestar de todos\u201D",ico:"\u{1F30F}",texto:"Que nadie quede atr\xE1s: vida simple, trabajo digno, no-violencia (ahimsa) y econom\xEDa al servicio del \xFAltimo. El progreso verdadero se mide por la felicidad del m\xE1s humilde."},{nombre:"Tri Hita Karana",pueblo:"Bali \xB7 Indonesia",conti:"Asia",sig:"\u201Ctres causas de armon\xEDa\u201D",ico:"\u{1F30F}",texto:"Armon\xEDa en tres direcciones: con lo sagrado (Parahyangan), entre humanos (Pawongan) y con la naturaleza (Palemahan). Los arrozales subak se riegan por acuerdo comunitario y rito, no por competencia."},{nombre:"Satoyama",pueblo:"Jap\xF3n rural",conti:"Asia",sig:"\u201Cvivir entre monte y aldea\u201D",ico:"\u{1F30F}",texto:"Paisaje donde bosque, chacra, agua y aldea se cuidan en ciclo: le\xF1a medida, compost, bosque comestible y fiesta estacional. El humano es jardinero del equilibrio, no due\xF1o del monte."},{nombre:"Gotong Royong",pueblo:"Java \xB7 Indonesia",conti:"Asia",sig:"\u201Ccargar juntos la carga\u201D",ico:"\u{1F30F}",texto:"Ayuda mutua como deber cotidiano: reparar el camino, levantar la casa o preparar la fiesta entre todos. El peso repartido pesa menos y el m\xE9rito es del barrio entero."},{nombre:"Bayanihan",pueblo:"Filipinas",conti:"Asia",sig:"\u201Clevantar la casa entre todos\u201D",ico:"\u{1F30F}",texto:"Todo el pueblo carga sobre sus hombros la casa del vecino para moverla a mejor suelo. Esp\xEDritu de hero\xEDsmo comunitario (bayani): servir sin esperar pago y celebrar despu\xE9s con mesa com\xFAn."},{nombre:"Kaitiakitanga",pueblo:"Pueblo Maor\xED \xB7 Aotearoa (N. Zelanda)",conti:"Ocean\xEDa",sig:"\u201Cguardian\xEDa viva\u201D",ico:"\u{1F30A}",texto:"Ser kaitiaki: guardi\xE1n del r\xEDo, del bosque y del mar, por las generaciones que vienen. El r\xEDo es ancestro (tupuna), no recurso: si el agua enferma, la gente enferma. Cuidar es devolver el mauri (fuerza vital)."},{nombre:"M\u0101lama \u02BB\u0100ina",pueblo:"K\u0101naka Maoli \xB7 Haw\xE1i",conti:"Ocean\xEDa",sig:"\u201Ccuidar la tierra que alimenta\u201D",ico:"\u{1F30A}",texto:"La tierra (\u02BB\u0101ina) es la que da de comer y por eso es familia. Trabajar el taro, limpiar el estero y repartir la cosecha mantienen el aloha \u02BB\u0101ina: amor que se practica cuidando."},{nombre:"Vanua",pueblo:"Fiyi y Melanesia",conti:"Ocean\xEDa",sig:"\u201Ctierra, gente y esp\xEDritu son uno\u201D",ico:"\u{1F30A}",texto:"Vanua no es solo suelo: es la trama viva entre tierra, mar, ancestros, comunidad y esp\xEDritu. Cuidar el arrecife y el taro es cuidar el nombre y el futuro del pueblo."},{nombre:"Caring for Country",pueblo:"Pueblos abor\xEDgenes \xB7 Australia",conti:"Ocean\xEDa",sig:"\u201Ccuidar el Country\u201D",ico:"\u{1F30A}",texto:"El Country \u2014tierra, agua, cielo, canto y ancestro\u2014 necesita su gente y su fuego bueno. Quemas cuidadas, lectura de huellas y ley viva: si el Country est\xE1 sano, la gente est\xE1 sana."},{nombre:"H\xF3zh\xF3",pueblo:"Pueblo Din\xE9 (Navajo)",conti:"Norteam\xE9rica",sig:"\u201Cbelleza, equilibrio\u201D",ico:"\u{1F985}",texto:"Caminar en belleza: salud, pensamiento, palabra y acto en equilibrio con la tierra, el cielo y la comunidad. La enfermedad es desarmon\xEDa; sanar es restaurar la relaci\xF3n con todo."},{nombre:"S\xE9ptima Generaci\xF3n",pueblo:"Haudenosaunee \xB7 noreste",conti:"Norteam\xE9rica",sig:"\u201Cpensar siete generaciones\u201D",ico:"\u{1F985}",texto:"Toda decisi\xF3n debe cuidar a quienes nacer\xE1n siete generaciones despu\xE9s. El consejo escucha a los ni\xF1os, a los ancianos y a la naturaleza antes de actuar: el futuro tambi\xE9n vota."},{nombre:"Mitakuye Oyasin",pueblo:"Pueblo Lakota \xB7 llanuras",conti:"Norteam\xE9rica",sig:"\u201Ctodos somos parientes\u201D",ico:"\u{1F985}",texto:"Oraci\xF3n y ley a la vez: el b\xFAfalo, el r\xEDo, la piedra y el humano son familia. Nada se toma sin rezo ni se deja sin ofrenda; da\xF1ar a uno es da\xF1arse a s\xED mismo."},{nombre:"Potlatch",pueblo:"Pueblos de la costa noroeste",conti:"Norteam\xE9rica",sig:"\u201Cdar es ser rico\u201D",ico:"\u{1F985}",texto:"Fiesta de reparto: quien m\xE1s da, m\xE1s honor recibe. Mantas, salm\xF3n y cantos circulan para equilibrar la comunidad. La riqueza guardada averg\xFCenza; la riqueza repartida nombra jefes."},{nombre:"Friluftsliv",pueblo:"Pueblos n\xF3rdicos \xB7 Noruega",conti:"Europa",sig:"\u201Cvida al aire libre\u201D",ico:"\u{1F3D4}\uFE0F",texto:"Vivir afuera, simple y cerca: caminar, esquiar, acampar y compartir caba\xF1a sin lujo. El derecho de paso (allemannsretten) dice que la naturaleza es de todos si se pisa con respeto. Lo suficiente abriga igual."},{nombre:"Lagom",pueblo:"Suecia",conti:"Europa",sig:"\u201Cni mucho ni poco, lo justo\u201D",ico:"\u{1F3D4}\uFE0F",texto:"La medida sueca de lo suficiente: tomar lo que toca y dejar para el otro, en la mesa, en el trabajo y en el bosque. Equilibrio sin alarde que cuida al grupo y al recurso."},{nombre:"Auzolan",pueblo:"Euskal Herria \xB7 pueblo vasco",conti:"Europa",sig:"\u201Cfaena vecinal\u201D",ico:"\u{1F3D4}\uFE0F",texto:"Trabajo comunal de vecindad: arreglar el camino, la frontonera o el caser\xEDo entre todos, a mano vuelta. Lo que es de todos se cuida entre todos, con palabra y kaldero compartido."}],B=[{ico:"\u{1F4A7}",t:"Cuida el agua",d:"Ducha corta, repara goteos, riega al atardecer. El agua no se gasta: se devuelve limpia."},{ico:"\u267B\uFE0F",t:"Reutiliza y recicla",d:"Separa vidrio, pl\xE1stico, papel y aceite. Lleva al punto limpio; lo org\xE1nico al compost."},{ico:"\u{1F96C}",t:"Consume local y de estaci\xF3n",d:"Feria de Penco, trueque con vecinos, huerta propia. Menos envase, m\xE1s territorio."},{ico:"\u{1F91D}",t:"Haz minga",d:"Una mano lava la otra: ayuda en cosechas, techos o limpieza de quebrada. An\xF3tala y convoca."},{ico:"\u{1F331}",t:"Planta nativo",d:"Peumo, quillay, boldo, chilco en Pukem con lluvia. En el cerro: foto antes que muestra."},{ico:"\u{1F525}",t:"Energ\xEDa justa",d:"Le\xF1a seca, olla tapada, luz solo donde est\xE1s. Lo suficiente abriga igual."},{ico:"\u{1F64F}",t:"Agradece y pide permiso",d:"Llellipun antes de cortar, gratitud despu\xE9s de recibir. Devuelve algo siempre."},{ico:"\u{1F5E3}\uFE0F",t:"Transmite",d:"Ense\xF1a un oficio, graba a tus abuelos, cuenta un epew. La memoria tambi\xE9n se siembra."}],P=["\u{1F4A7} Agua","\u267B\uFE0F Residuos","\u{1F96C} Consumo","\u{1F91D} Comunidad","\u{1F331} Territorio","\u{1F525} Energ\xEDa","\u{1F64F} Esp\xEDritu"];function m(){var a=j("buenVivir",{compromisos:[]});if(!a||!Array.isArray(a.compromisos))try{var e=userData();return e.buenVivir={compromisos:[]},e.buenVivir}catch{return{compromisos:[]}}return a}function M(){var a=[];try{a=m().compromisos||[]}catch{}var e=a.filter(function(o){return o.hecho}).length;return{total:a.length,hechas:e}}function S(a){if(!a.length)return"\u{1F30E} Mis compromisos del Buen Vivir \u2014 a\xFAn sin registros";var e="\u{1F30E} Mis compromisos del Buen Vivir \xB7 "+a.length+`

